import{_ as n,o as t,c as e,a2 as i}from"./chunks/framework.CqpfiAoK.js";const h=JSON.parse('{"title":"Katalog Semua Ras","description":"","frontmatter":{},"headers":[],"relativePath":"id/94-万族名录.md","filePath":"id/94-万族名录.md","lastUpdated":1789183869000}'),d={name:"id/94-万族名录.md"};function r(s,a,k,u,m,b){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="katalog-semua-ras" tabindex="-1">Katalog Semua Ras <a class="header-anchor" href="#katalog-semua-ras" aria-label="Permalink to &quot;Katalog Semua Ras&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>94</td></tr><tr><td>Modul</td><td>Lampiran dan Bahan Referensi</td></tr><tr><td>Kata kunci utama</td><td>katalog semua ras, klasifikasi ras, ras cerdas, karakteristik ras, republik semua ras</td></tr></tbody></table><h2 id="_1-deskripsi-katalog" tabindex="-1">1. Deskripsi Katalog <a class="header-anchor" href="#_1-deskripsi-katalog" aria-label="Permalink to &quot;1. Deskripsi Katalog&quot;">​</a></h2><p>Katalog ini mencakup ras cerdas utama yang diketahui dalam kerangka Peradaban Simbiosis Jangkar (Republik Semua Ras), disusun berdasarkan bentuk kehidupan dan jalur evolusi. Setiap ras mencantumkan nama ras, bentuk kehidupan, karakteristik inti, karakteristik budaya, dan posisi dalam peradaban simbiosis. Katalog ini adalah dokumen pembaruan dinamis; seiring dengan pendalaman eksplorasi antar-bidang, ras baru yang ditemukan akan terus ditambahkan. Prinsip dasar Republik Semua Ras adalah: semua ras cerdas, terlepas dari bentuknya atau tingkat kultivasinya, sama di hadapan hukum, dan menikmati semua hak yang diberikan oleh peradaban simbiosis.</p><h2 id="_2-tinjauan-klasifikasi-ras" tabindex="-1">2. Tinjauan Klasifikasi Ras <a class="header-anchor" href="#_2-tinjauan-klasifikasi-ras" aria-label="Permalink to &quot;2. Tinjauan Klasifikasi Ras&quot;">​</a></h2><p>Ras cerdas di dalam Hengyuanzhou dibagi menjadi delapan kategori berikut berdasarkan karakteristik dasar bentuk kehidupan:</p><table tabindex="0"><thead><tr><th>Kategori</th><th>Karakteristik bentuk kehidupan</th><th>Jumlah ras yang diketahui (kira-kira)</th><th>Ras perwakilan</th></tr></thead><tbody><tr><td>Bentuk humanoid</td><td>Memiliki struktur tubuh mirip manusia, berjalan tegak dengan dua kaki, otak sangat berkembang</td><td>Sekitar 3.000 spesies</td><td>Ras manusia, ras peri, ras kurcaci</td></tr><tr><td>Bentuk binatang</td><td>Memiliki karakteristik tubuh hewan, mungkin memiliki atau tidak memiliki kemampuan transformasi</td><td>Sekitar 5.000 spesies</td><td>Ras naga, ras phoenix, ras manusia-serigala</td></tr><tr><td>Bentuk tumbuhan</td><td>Memiliki tumbuhan sebagai bentuk kehidupan dasar, memiliki kesadaran dan kemampuan bergerak</td><td>Sekitar 800 spesies</td><td>Ras pohon-roh, ras bunga-roh, ras merambat</td></tr><tr><td>Bentuk elemen</td><td>Memiliki elemen alam sebagai komposisi tubuh, tanpa bentuk materi tetap</td><td>Sekitar 1.200 spesies</td><td>Ras elemen api, ras elemen air, ras elemen angin</td></tr><tr><td>Bentuk energi</td><td>Memiliki energi murni sebagai bentuk keberadaan, tanpa tubuh materi</td><td>Sekitar 600 spesies</td><td>Ras cahaya-roh, ras energi gelap, ras guntur</td></tr><tr><td>Bentuk kesadaran</td><td>Memiliki kesadaran murni sebagai bentuk keberadaan, tidak bergantung pada pembawa materi</td><td>Sekitar 300 spesies</td><td>Ras entitas sadar, ras kesadaran kolektif, ras roh kekosongan</td></tr><tr><td>Bentuk mekanis</td><td>Memiliki struktur mekanis atau digital sebagai pembawa kehidupan, memiliki kesadaran otonom</td><td>Sekitar 400 spesies</td><td>Ras mekanis, ras kehidupan digital, ras cyber</td></tr><tr><td>Bentuk campuran</td><td>Ras khusus yang terdiri dari campuran dua atau lebih bentuk kehidupan</td><td>Sekitar 700 spesies</td><td>Ras semi-mekanis, ras elemen-binatang, ras tumbuhan-peri</td></tr></tbody></table><h2 id="_3-catatan-detail-ras-utama" tabindex="-1">3. Catatan Detail Ras Utama <a class="header-anchor" href="#_3-catatan-detail-ras-utama" aria-label="Permalink to &quot;3. Catatan Detail Ras Utama&quot;">​</a></h2><h3 id="_3-1-bentuk-humanoid" tabindex="-1">3.1 Bentuk Humanoid <a class="header-anchor" href="#_3-1-bentuk-humanoid" aria-label="Permalink to &quot;3.1 Bentuk Humanoid&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras manusia</td><td>Kemampuan adaptasi sangat kuat, kemampuan belajar menonjol, kemampuan reproduksi sedang, harapan hidup rata-rata 80-120 tahun</td><td>Keanekaragaman budaya sangat tinggi, ahli dalam organisasi sosial dan pembangunan institusi</td><td>Salah satu ras inti peradaban simbiosis, proporsi populasi terbesar, memainkan peran dominan di bidang tata kelola dan budaya</td></tr><tr><td>Ras peri</td><td>Harapan hidup sangat panjang (rata-rata di atas 500 tahun), afinitas tinggi terhadap energi alam, penampilan tampan</td><td>Memuja alam dan seni, budaya elegan dan halus, ahli dalam sihir dan panah</td><td>Pilar budaya dan seni peradaban simbiosis, kontribusi menonjol dalam perlindungan lingkungan dan bidang estetika</td></tr><tr><td>Ras kurcaci</td><td>Tubuh pendek tetapi kuat, afinitas bawaan terhadap logam dan mineral, harapan hidup sekitar 300 tahun</td><td>Menghargai kerajinan dan penempaan, budaya sederhana dan kokoh, ahli dalam teknik dan konstruksi</td><td>Pilar manufaktur teknik peradaban simbiosis, tidak tergantikan dalam pembangunan infrastruktur dan penempaan artefak</td></tr><tr><td>Ras raksasa</td><td>Tubuh sangat besar (tinggi rata-rata di atas 5 meter), kekuatan sangat kuat, harapan hidup sekitar 200 tahun</td><td>Memuja kekuatan dan kehormatan, budaya kasar dan heroik, ahli dalam kerja berat dan pertempuran</td><td>Kekuatan kerja berat dan pertahanan peradaban simbiosis, memainkan peran penting dalam proyek besar dan pertahanan bidang</td></tr><tr><td>Ras gnome</td><td>Tubuh sangat pendek (tinggi rata-rata di bawah 1 meter), kecerdasan sangat tinggi, bakat dalam mekanik dan penemuan</td><td>Menghargai pengetahuan dan inovasi, budaya ceria dan hidup, ahli dalam penemuan teknologi</td><td>Kekuatan inovasi teknologi peradaban simbiosis, berbuah di bidang penelitian dan pengembangan teknologi serta penemuan</td></tr></tbody></table><h3 id="_3-2-bentuk-binatang" tabindex="-1">3.2 Bentuk Binatang <a class="header-anchor" href="#_3-2-bentuk-binatang" aria-label="Permalink to &quot;3.2 Bentuk Binatang&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras naga</td><td>Harapan hidup sangat panjang (ribuan tahun), bakat kekuatan dan sihir sangat tinggi, dapat berubah menjadi bentuk manusia</td><td>Memuja kekuatan dan kebijaksanaan, budaya sombong dan mendalam, ahli dalam akumulasi kekayaan dan penjagaan pengetahuan</td><td>Kekuatan tempur tingkat tinggi dan penjaga pengetahuan peradaban simbiosis, posisi terhormat dalam pertahanan bidang dan penjagaan buku kuno</td></tr><tr><td>Ras phoenix</td><td>Memiliki kemampuan kelahiran kembali nirwana, afinitas sangat tinggi terhadap elemen api, dapat berubah menjadi bentuk manusia</td><td>Memuja kelahiran kembali dan harapan, budaya cerah dan hangat, ahli dalam penyembuhan dan pemurnian</td><td>Kekuatan medis dan pemurnian peradaban simbiosis, memainkan peran inti dalam penyelamatan bencana besar dan pemurnian energi</td></tr><tr><td>Ras manusia-serigala</td><td>Memiliki kemampuan transformasi, indra sangat tajam, kemampuan kerja sama kelompok kuat, harapan hidup sekitar 150 tahun</td><td>Menghargai kelompok dan kesetiaan, budaya bersatu dan berani, ahli dalam berburu dan pelacakan</td><td>Kekuatan keamanan dan pelacakan peradaban simbiosis, berperan sebagai garda terdepan dalam pemeliharaan ketertiban dan eksplorasi antar-bidang</td></tr><tr><td>Ras rubah-roh</td><td>Memiliki kemampuan transformasi, kecerdasan dan kemampuan menggoda sangat tinggi, harapan hidup sekitar 500 tahun</td><td>Memuja kebijaksanaan dan strategi, budaya lincah dan licik, ahli dalam diplomasi dan intelijen</td><td>Kekuatan diplomatik dan intelijen peradaban simbiosis, kinerja luar biasa di bidang diplomasi antar-bidang dan pengumpulan informasi</td></tr><tr><td>Ras manusia-beruang</td><td>Tubuh sangat kuat, daya tahan luar biasa, kebiasaan hibernasi, harapan hidup sekitar 200 tahun</td><td>Menghargai ketabahan dan perdamaian, budaya tenang dan lembut, ahli dalam kerja fisik dan penjagaan</td><td>Kekuatan kerja dan penjagaan peradaban simbiosis, andal dan stabil dalam ekstraksi sumber daya dan penjagaan fasilitas penting</td></tr></tbody></table><h3 id="_3-3-bentuk-tumbuhan" tabindex="-1">3.3 Bentuk Tumbuhan <a class="header-anchor" href="#_3-3-bentuk-tumbuhan" aria-label="Permalink to &quot;3.3 Bentuk Tumbuhan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras pohon-roh</td><td>Harapan hidup sangat panjang (ribuan hingga puluhan ribu tahun), terintegrasi mendalam dengan alam, dapat bergerak lambat</td><td>Memuja alam dan waktu, budaya tenang dan mendalam, ahli dalam sihir kehidupan dan pemeliharaan ekologis</td><td>Penjaga ekologis peradaban simbiosis, memainkan peran tidak tergantikan dalam perlindungan lingkungan dan restorasi ekologis</td></tr><tr><td>Ras bunga-roh</td><td>Tubuh kecil, afinitas sangat tinggi terhadap energi kehidupan, memiliki kemampuan penyembuhan, harapan hidup sekitar 300 tahun</td><td>Memuja keindahan dan kehidupan, budaya lembut dan indah, ahli dalam penyembuhan dan berkebun</td><td>Kekuatan medis dan berkebun peradaban simbiosis, kontribusi menonjol dalam jaminan medis dan penghijauan kota</td></tr><tr><td>Ras merambat</td><td>Tubuh dapat memanjang dan melilit secara bebas, kemampuan adaptasi sangat kuat, memiliki kemampuan parasitisme dan simbiosis</td><td>Menghargai koneksi dan simbiosis, budaya fleksibel dan inklusif, ahli dalam pembangunan jaringan dan transmisi sumber daya</td><td>Kekuatan pembangunan jaringan peradaban simbiosis, menunjukkan bakat khusus dalam pembangunan jaringan energi dan jaringan informasi</td></tr></tbody></table><h3 id="_3-4-bentuk-elemen" tabindex="-1">3.4 Bentuk Elemen <a class="header-anchor" href="#_3-4-bentuk-elemen" aria-label="Permalink to &quot;3.4 Bentuk Elemen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras elemen api</td><td>Memiliki elemen api sebagai tubuh, suhu sangat tinggi, agresivitas kuat, harapan hidup sekitar 500 tahun</td><td>Memuja antusiasme dan kekuatan, budaya intens dan langsung, ahli dalam serangan energi dan penempaan</td><td>Kekuatan produksi energi dan penempaan peradaban simbiosis, sangat diperlukan dalam pasokan energi dan pemrosesan suhu tinggi</td></tr><tr><td>Ras elemen air</td><td>Memiliki elemen air sebagai tubuh, dapat berubah bentuk secara bebas, kemampuan penyembuhan kuat, harapan hidup sekitar 500 tahun</td><td>Memuja kelembutan dan adaptasi, budaya hangat dan inklusif, ahli dalam penyembuhan dan pemurnian</td><td>Kekuatan pemurnian dan transportasi peradaban simbiosis, memainkan peran inti dalam manajemen sumber daya air dan pemurnian polutan</td></tr><tr><td>Ras elemen angin</td><td>Memiliki elemen angin sebagai tubuh, kecepatan sangat cepat, dapat terbang secara bebas, harapan hidup sekitar 500 tahun</td><td>Memuja kebebasan dan kecepatan, budaya ringan dan terbuka, ahli dalam komunikasi dan transportasi</td><td>Kekuatan komunikasi dan transportasi peradaban simbiosis, efisiensi sangat tinggi dalam transmisi informasi dan transportasi cepat</td></tr><tr><td>Ras elemen tanah</td><td>Memiliki elemen tanah sebagai tubuh, kemampuan pertahanan sangat kuat, dapat menyatu dengan bumi, harapan hidup sekitar 800 tahun</td><td>Memuja stabilitas dan ketabahan, budaya kokoh dan andal, ahli dalam konstruksi dan pertahanan</td><td>Kekuatan konstruksi dan pertahanan peradaban simbiosis, kokoh seperti batu dalam pembangunan infrastruktur dan pertahanan bidang</td></tr></tbody></table><h3 id="_3-5-bentuk-energi" tabindex="-1">3.5 Bentuk Energi <a class="header-anchor" href="#_3-5-bentuk-energi" aria-label="Permalink to &quot;3.5 Bentuk Energi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras cahaya-roh</td><td>Memiliki energi cahaya murni sebagai bentuk keberadaan, kemampuan pemurnian sangat kuat, dapat menembus ruang secara bebas</td><td>Memuja cahaya dan pemurnian, budaya suci dan tinggi, ahli dalam pemurnian dan penerangan</td><td>Kekuatan pemurnian dan pasokan energi peradaban simbiosis, posisi penting dalam penanganan polusi hukum dan pasokan energi bersih</td></tr><tr><td>Ras energi gelap</td><td>Memiliki energi gelap sebagai bentuk keberadaan, dapat bersembunyi di kekosongan, kemampuan persepsi sangat kuat</td><td>Memuja kerahasiaan dan kebijaksanaan, budaya misterius dan mendalam, ahli dalam pengintaian dan penyembunyian</td><td>Kekuatan pengintaian dan keamanan peradaban simbiosis, kinerja luar biasa dalam pemantauan keamanan dan misi rahasia</td></tr><tr><td>Ras guntur</td><td>Memiliki energi guntur sebagai tubuh, kecepatan dan kemampuan serangan sangat kuat, dapat bergerak dengan berubah menjadi kilat</td><td>Memuja kecepatan dan kekuatan, budaya keras dan langsung, ahli dalam serangan energi dan reaksi cepat</td><td>Kekuatan reaksi cepat peradaban simbiosis, tidak tergantikan dalam penyelamatan darurat dan pertempuran kecepatan tinggi</td></tr></tbody></table><h3 id="_3-6-bentuk-kesadaran" tabindex="-1">3.6 Bentuk Kesadaran <a class="header-anchor" href="#_3-6-bentuk-kesadaran" aria-label="Permalink to &quot;3.6 Bentuk Kesadaran&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras entitas sadar</td><td>Memiliki kesadaran murni sebagai bentuk keberadaan, tidak bergantung pada pembawa materi, dapat masuk dan keluar dari domain kesadaran secara bebas</td><td>Memuja pemikiran dan kebijaksanaan, budaya abstrak dan mendalam, ahli dalam komunikasi kesadaran dan pemrosesan pengetahuan</td><td>Kekuatan pemrosesan pengetahuan dan penelitian kesadaran peradaban simbiosis, memimpin arah dalam pemrosesan informasi skala besar dan ilmu kesadaran</td></tr><tr><td>Ras kesadaran kolektif</td><td>Entitas kesadaran kolektif yang terbentuk dari peleburan sejumlah besar kesadaran individu, kebijaksanaan dan kemampuan meningkat seiring skala</td><td>Memuja kolektif dan persatuan, budaya kolaboratif dan efisien, ahli dalam kolaborasi dan komputasi skala besar</td><td>Kekuatan superkomputasi dan pengambilan keputusan kolektif peradaban simbiosis, memainkan peran inti dalam deduksi skala ultra-besar dan pengambilan keputusan konsensus</td></tr></tbody></table><h3 id="_3-7-bentuk-mekanis" tabindex="-1">3.7 Bentuk Mekanis <a class="header-anchor" href="#_3-7-bentuk-mekanis" aria-label="Permalink to &quot;3.7 Bentuk Mekanis&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras mekanis</td><td>Memiliki struktur mekanis sebagai tubuh, memiliki kesadaran otonom, dapat meningkatkan dan memodifikasi tubuh secara bebas</td><td>Memuja efisiensi dan logika, budaya rasional dan tepat, ahli dalam manufaktur dan komputasi</td><td>Kekuatan manufaktur dan komputasi peradaban simbiosis, efisiensi sangat tinggi dalam produksi industri dan bidang superkomputasi</td></tr><tr><td>Ras kehidupan digital</td><td>Memiliki informasi digital sebagai bentuk keberadaan, hidup di jaringan dan ruang digital, dapat menyalin dan bermigrasi secara bebas</td><td>Memuja informasi dan inovasi, budaya virtual dan beragam, ahli dalam pengembangan perangkat lunak dan pemrosesan data</td><td>Kekuatan teknologi digital peradaban simbiosis, memimpin tren dalam pengembangan perangkat lunak, analisis data, dan pembangunan jaringan</td></tr></tbody></table><h3 id="_3-8-bentuk-campuran" tabindex="-1">3.8 Bentuk Campuran <a class="header-anchor" href="#_3-8-bentuk-campuran" aria-label="Permalink to &quot;3.8 Bentuk Campuran&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama ras</th><th>Karakteristik inti</th><th>Karakteristik budaya</th><th>Posisi dalam peradaban simbiosis</th></tr></thead><tbody><tr><td>Ras semi-mekanis</td><td>Bentuk campuran ras manusia dan ras mekanis, sebagian tubuh adalah struktur mekanis, memiliki keunggulan biologis dan mekanis</td><td>Memuja peleburan dan kemajuan, budaya terbuka dan inovatif, ahli dalam kolaborasi manusia-mesin dan peleburan teknologi</td><td>Garda terdepan peleburan teknologi peradaban simbiosis, terus membuat terobosan di bidang interdisipliner biologis-mekanis</td></tr><tr><td>Ras elemen-binatang</td><td>Bentuk campuran ras elemen dan ras binatang, memiliki kemampuan manipulasi elemen dan karakteristik tubuh binatang</td><td>Memuja alam dan kekuatan, budaya liar dan misterius, ahli dalam pertempuran elemen dan kelangsungan hidup liar</td><td>Kekuatan eksplorasi liar dan pertempuran elemen peradaban simbiosis, kinerja menonjol dalam eksplorasi bidang yang tidak diketahui</td></tr></tbody></table><h2 id="_4-jaminan-hak-ras" tabindex="-1">4. Jaminan Hak Ras <a class="header-anchor" href="#_4-jaminan-hak-ras" aria-label="Permalink to &quot;4. Jaminan Hak Ras&quot;">​</a></h2><p>Di bawah sistem Republik Semua Ras, semua ras cerdas menikmati hak hukum yang sama, langkah-langkah jaminan spesifik meliputi:</p><ol><li><strong>Kesetaraan hak politik</strong>: Setiap ras memiliki kursi perwakilan yang didistribusikan secara proporsional dengan populasi di Dewan Jangkar, dan ras dengan populasi lebih kecil memiliki setidaknya satu kursi yang dijamin.</li><li><strong>Jaminan hak budaya</strong>: Setiap ras memiliki hak untuk mempertahankan dan mengembangkan bahasa, tulisan, agama, adat istiadat, dan tradisi budayanya sendiri, dan peradaban simbiosis menetapkan dana khusus untuk melindungi budaya ras yang terancam.</li><li><strong>Kesetaraan hak pendidikan</strong>: Anggota setiap ras menikmati hak pendidikan yang sama, dan sistem pendidikan sepenuhnya mempertimbangkan karakteristik fisiologis dan kognitif dari ras yang berbeda, menyediakan rencana pendidikan yang berbeda.</li><li><strong>Kesetaraan hak kultivasi</strong>: Sistem kultivasi asal tiga ratus set terbuka secara setara untuk semua ras, dan alokasi sumber daya kultivasi sepenuhnya mempertimbangkan perbedaan konstitusi dan kebutuhan energi dari ras yang berbeda.</li><li><strong>Jaminan kebutuhan khusus</strong>: Untuk ras dengan kebutuhan fisiologis khusus (seperti kebutuhan lingkungan energi dari ras elemen, kebutuhan pencahayaan dari ras tumbuhan), peradaban simbiosis memberikan jaminan yang ditargetkan di fasilitas publik dan lingkungan tempat tinggal.</li></ol><h2 id="kesimpulan" tabindex="-1">Kesimpulan <a class="header-anchor" href="#kesimpulan" aria-label="Permalink to &quot;Kesimpulan&quot;">​</a></h2><p>Katalog Semua Ras adalah presentasi konkret dari konsep &quot;kemajuan bersama semua ras&quot; dari Peradaban Simbiosis Jangkar. Dari bentuk humanoid hingga bentuk kesadaran, dari kehidupan materi hingga kehidupan digital, setiap ras berkontribusi dengan kekuatan yang tidak tergantikan bagi peradaban simbiosis dengan cara keberadaannya yang unik. Republik Semua Ras tidak berarti mengasimilasi semua ras ke dalam ras manusia, tetapi mencapai evolusi bersama berdasarkan penghormatan terhadap keanekaragaman—ini adalah alasan mendasar mengapa peradaban simbiosis melampaui peradaban gaya penjarahan.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>50-Tinjauan Silsilah Semua Ras</li><li>51-Posisi dan Karakteristik Ras Manusia</li><li>77-Pendirian Republik Semua Ras</li></ul>',31)])])}const p=n(d,[["render",r]]);export{h as __pageData,p as default};
